-- Cloud integration test: temporary synthetic users, all data rolled back.
begin;
create function pg_temp.must_fail(command text) returns void language plpgsql as $$
begin
 begin execute command; exception when others then return; end;
 raise exception 'FAIL: unauthorized/invalid operation succeeded: %',command;
end $$;
create function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$
begin if value is not true then raise exception 'FAIL: %',label; end if; end $$;
select set_config('rf.test.leader',gen_random_uuid()::text,true),set_config('rf.test.member',gen_random_uuid()::text,true),set_config('rf.test.supervisor',gen_random_uuid()::text,true),set_config('rf.test.outsider',gen_random_uuid()::text,true);
insert into auth.users(id,email,email_confirmed_at,raw_user_meta_data)
select current_setting('rf.test.'||n)::uuid,'rf-mvp2-'||current_setting('rf.test.'||n)||'@example.invalid',now(),jsonb_build_object('full_name','MVP2 test '||n) from unnest(array['leader','member','supervisor','outsider']) n;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select set_config('rf.test.w',public.rf_create_workspace('MVP2 test team','Isolated test research','Test Leader')::text,true);
select pg_temp.assert_true((select count(*)=7 from public.rf_channels where workspace_id=current_setting('rf.test.w')::uuid),'seven default channels');
select pg_temp.assert_true((select count(*)=10 from public.rf_document_folders where workspace_id=current_setting('rf.test.w')::uuid),'ten default folders');
insert into public.rf_workspace_invitations(workspace_id,email,role) select current_setting('rf.test.w')::uuid,'rf-mvp2-'||current_setting('rf.test.'||n)||'@example.invalid',n from unnest(array['member','supervisor']) n;
select set_config('rf.test.tokenmember',(select token::text from public.rf_workspace_invitations where workspace_id=current_setting('rf.test.w')::uuid and role='member'),true),set_config('rf.test.tokensupervisor',(select token::text from public.rf_workspace_invitations where workspace_id=current_setting('rf.test.w')::uuid and role='supervisor'),true);
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select public.rf_accept_invitation(current_setting('rf.test.tokenmember')::uuid,'Test Member');
select set_config('request.jwt.claim.sub',current_setting('rf.test.supervisor'),true);
select public.rf_accept_invitation(current_setting('rf.test.tokensupervisor')::uuid,'Test Supervisor');
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select set_config('rf.test.channel',(public.rf_collaborate('channel_save',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'name','Test channel'))->>'id'),true);
select set_config('rf.test.folder',(select id::text from public.rf_document_folders where workspace_id=current_setting('rf.test.w')::uuid limit 1),true);
select set_config('rf.test.private',(public.rf_collaborate('document_create',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'folder_id',current_setting('rf.test.folder'),'title','Confidential research','restricted',true))->>'id'),true);
select set_config('rf.test.path',current_setting('rf.test.w')||'/'||current_setting('rf.test.leader')||'/'||gen_random_uuid()||'.txt',true);
reset role;
insert into storage.objects(bucket_id,name,metadata) values('researchflow-files',current_setting('rf.test.path'),'{"mimetype":"text/plain","size":12}');
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select set_config('rf.test.version',(public.rf_collaborate('file_register',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'path',current_setting('rf.test.path'),'name','notes.txt','document_id',current_setting('rf.test.private')))->>'id'),true);
select pg_temp.assert_true((select version=1 from public.rf_document_versions where id=current_setting('rf.test.version')::uuid),'version one persisted');
select pg_temp.must_fail(format('select public.rf_collaborate(''file_register'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'path',current_setting('rf.test.path'),'name','duplicate.txt','document_id',current_setting('rf.test.private'))));
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select pg_temp.assert_true((select count(*)=0 from public.rf_documents where id=current_setting('rf.test.private')::uuid),'restricted document hidden from member');
select pg_temp.assert_true((select count(*)=0 from storage.objects where name=current_setting('rf.test.path')),'restricted file hidden from member');
select pg_temp.must_fail(format('select public.rf_collaborate(''announcement_save'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'title','Unauthorized','body','Unauthorized','priority','Normal')));
select pg_temp.must_fail(format('select public.rf_collaborate(''channel_save'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'name','Unauthorized')));
select pg_temp.must_fail(format('insert into public.rf_messages(workspace_id,channel_id,author_id,body) values(%L,%L,%L,''Bypass'')',current_setting('rf.test.w'),current_setting('rf.test.channel'),current_setting('rf.test.member')));
select set_config('rf.test.message',(public.rf_collaborate('message_send',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'channel_id',current_setting('rf.test.channel'),'body','Persisted message'))->>'id'),true);
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select pg_temp.assert_true((select unread_count=1 from public.rf_channel_unread where channel_id=current_setting('rf.test.channel')::uuid),'unread count persisted');
select public.rf_collaborate('channel_read',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'channel_id',current_setting('rf.test.channel'),'last_read_at',now()));
select pg_temp.assert_true((select unread_count=0 from public.rf_channel_unread where channel_id=current_setting('rf.test.channel')::uuid),'read cursor persisted');
select pg_temp.must_fail(format('select public.rf_collaborate(''message_edit'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'id',current_setting('rf.test.message'),'body','Impersonation')));
select public.rf_collaborate('document_access',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'id',current_setting('rf.test.private'),'restricted',true,'readers',jsonb_build_array(current_setting('rf.test.member'))));
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select pg_temp.assert_true((select count(*)=1 from public.rf_documents where id=current_setting('rf.test.private')::uuid),'assigned restricted reader can read');
select pg_temp.assert_true((select count(*)=1 from storage.objects where name=current_setting('rf.test.path')),'assigned restricted reader can access storage');
select set_config('rf.test.path2',current_setting('rf.test.w')||'/'||current_setting('rf.test.member')||'/'||gen_random_uuid()||'.txt',true);
reset role;
insert into storage.objects(bucket_id,name,metadata) values('researchflow-files',current_setting('rf.test.path2'),'{"mimetype":"text/plain","size":20}');
set local role authenticated;
select set_config('rf.test.version',(public.rf_collaborate('file_register',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'path',current_setting('rf.test.path2'),'name','notes-v2.txt','document_id',current_setting('rf.test.private')))->>'id'),true);
select pg_temp.assert_true((select count(*)=2 and max(version)=2 from public.rf_document_versions where document_id=current_setting('rf.test.private')::uuid),'new versions preserve old files and metadata');
select set_config('rf.test.meeting',(public.rf_collaborate('meeting_save',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'title','Test meeting','type','Team Meeting','starts_at','2027-01-02T10:00:00Z','ends_at','2027-01-02T11:00:00Z','timezone','Asia/Colombo','participants',jsonb_build_array(current_setting('rf.test.leader'))))->>'id'),true);
select set_config('rf.test.action',(public.rf_collaborate('meeting_action',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'meeting_id',current_setting('rf.test.meeting'),'title','Meeting follow-up','assignee_id',current_setting('rf.test.member'),'due_date','2027-01-10'))->>'id'),true);
select public.rf_collaborate('meeting_note',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'meeting_id',current_setting('rf.test.meeting'),'kind','Minutes','body','An authored minutes revision'));
select pg_temp.must_fail(format('select public.rf_collaborate(''action_convert'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'id',current_setting('rf.test.action'))));
select set_config('rf.test.submission',(public.rf_collaborate('review_request',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'version_id',current_setting('rf.test.version')))->>'id'),true);
select pg_temp.must_fail(format('select public.rf_collaborate(''review_decide'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'submission_id',current_setting('rf.test.submission'),'kind','Academic','decision','Approved','feedback','Impersonation')));
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select set_config('rf.test.task',(public.rf_collaborate('action_convert',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'id',current_setting('rf.test.action')))->>'id'),true);
select pg_temp.assert_true(public.rf_collaborate('action_convert',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'id',current_setting('rf.test.action')))->>'id'=current_setting('rf.test.task'),'action conversion idempotent');
select public.rf_collaborate('review_decide',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'submission_id',current_setting('rf.test.submission'),'kind','Internal','decision','Approved','feedback','Internal team review'));
select pg_temp.assert_true((select status='Submitted for Review' and internal_status='Approved' from public.rf_submissions where id=current_setting('rf.test.submission')::uuid),'internal approval does not imply academic approval');
select set_config('request.jwt.claim.sub',current_setting('rf.test.supervisor'),true);
select public.rf_collaborate('review_decide',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'submission_id',current_setting('rf.test.submission'),'kind','Academic','decision','Revision Requested','feedback','Please revise the analysis'));
select pg_temp.assert_true((select status='Revision Requested' from public.rf_submissions where id=current_setting('rf.test.submission')::uuid),'supervisor decision persisted');
select pg_temp.must_fail(format('select public.rf_collaborate(''review_decide'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'submission_id',current_setting('rf.test.submission'),'kind','Academic','decision','Approved','feedback','Overwrite history')));
select set_config('request.jwt.claim.sub',current_setting('rf.test.outsider'),true);
select set_config('rf.test.other',public.rf_create_workspace('Other test workspace','Other research','Test Outsider')::text,true);
select pg_temp.assert_true((select count(*)=0 from public.rf_messages where workspace_id=current_setting('rf.test.w')::uuid),'cross workspace messages hidden');
select pg_temp.assert_true((select count(*)=0 from public.rf_meetings where workspace_id=current_setting('rf.test.w')::uuid),'cross workspace meetings hidden');
select pg_temp.assert_true((select count(*)=0 from public.rf_reviews where workspace_id=current_setting('rf.test.w')::uuid),'cross workspace reviews hidden');
select pg_temp.must_fail(format('select public.rf_collaborate(''message_send'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'channel_id',current_setting('rf.test.channel'),'body','Unauthorized')));
select pg_temp.must_fail(format('select public.rf_collaborate(''message_send'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.other'),'channel_id',current_setting('rf.test.channel'),'body','Cross workspace channel')));
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select public.rf_collaborate('message_delete',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'id',current_setting('rf.test.message')));
select pg_temp.assert_true((select body='' and deleted from public.rf_messages where id=current_setting('rf.test.message')::uuid),'message deletion removes body');
select public.rf_collaborate('announcement_save',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'title','Test announcement','body','Private announcement body','priority','Important','pinned',true));
select pg_temp.must_fail(format('update public.rf_audit_events set details=''{}'' where workspace_id=%L',current_setting('rf.test.w')));
select pg_temp.assert_true(not exists(select 1 from public.rf_audit_events where workspace_id=current_setting('rf.test.w')::uuid and (details?'body' or details?'content')),'audit avoids private contents');
select set_config('rf.test.phase',(select id::text from public.rf_research_phases where workspace_id=current_setting('rf.test.w')::uuid limit 1),true);
select pg_temp.must_fail(format('update public.rf_research_phases set review_state=''Approved'' where id=%L',current_setting('rf.test.phase')));
select set_config('rf.test.phase_submission',(public.rf_collaborate('review_request',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'phase_id',current_setting('rf.test.phase')))->>'id'),true);
select set_config('request.jwt.claim.sub',current_setting('rf.test.supervisor'),true);
select public.rf_collaborate('review_decide',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'submission_id',current_setting('rf.test.phase_submission'),'kind','Academic','decision','Approved','feedback','Milestone academically approved'));
select pg_temp.assert_true((select review_state='Approved' from public.rf_research_phases where id=current_setting('rf.test.phase')::uuid),'academic milestone decision updates phase');
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select set_config('rf.test.owned_doc',(public.rf_collaborate('document_create',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'folder_id',current_setting('rf.test.folder'),'title','Original member research','restricted',true))->>'id'),true);
select set_config('request.jwt.claim.sub',current_setting('rf.test.leader'),true);
select set_config('rf.test.path3',current_setting('rf.test.w')||'/'||current_setting('rf.test.leader')||'/'||gen_random_uuid()||'.txt',true);
reset role;
insert into storage.objects(bucket_id,name,metadata) values('researchflow-files',current_setting('rf.test.path3'),'{"mimetype":"text/plain","size":20}');
set local role authenticated;
select set_config('rf.test.owned_version',(public.rf_collaborate('file_register',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'path',current_setting('rf.test.path3'),'name','leader-revision.txt','document_id',current_setting('rf.test.owned_doc')))->>'id'),true);
select set_config('rf.test.owned_submission',(public.rf_collaborate('review_request',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'version_id',current_setting('rf.test.owned_version')))->>'id'),true);
select public.rf_manage_member(current_setting('rf.test.w')::uuid,current_setting('rf.test.supervisor')::uuid,'member');
select public.rf_manage_member(current_setting('rf.test.w')::uuid,current_setting('rf.test.member')::uuid,'supervisor');
select set_config('request.jwt.claim.sub',current_setting('rf.test.member'),true);
select pg_temp.must_fail(format('select public.rf_collaborate(''review_decide'',%L::jsonb)',jsonb_build_object('workspace_id',current_setting('rf.test.w'),'submission_id',current_setting('rf.test.owned_submission'),'kind','Academic','decision','Approved','feedback','Cannot approve original own research')));
select pg_temp.assert_true(not rf_private.unregistered_upload(current_setting('rf.test.path2')),'registered private files cannot be deleted through orphan cleanup');
reset role;
select pg_temp.assert_true((select count(*)=3 from pg_publication_tables where pubname='supabase_realtime' and tablename in ('rf_messages','rf_channels','rf_files')),'realtime tables published');
rollback;
select 'PASS: defaults, RLS, restricted storage, persisted messages and unread state, document version registration, meeting actions, idempotent task conversion, distinct academic/internal reviews, immutable history, cross-workspace isolation and metadata-only audit; all fixtures rolled back' as result;
